using FinancePro.Core.Entities; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace FinancePro.Data.Configurations;
public class ProdutoConfiguration : IEntityTypeConfiguration<Produto> { public void Configure(EntityTypeBuilder<Produto> b) { b.ToTable("Produtos"); b.HasKey(x=>x.Id); b.Property(x=>x.Codigo).HasMaxLength(40).IsRequired(); b.Property(x=>x.Nome).HasMaxLength(180).IsRequired(); b.Property(x=>x.Categoria).HasMaxLength(100); b.Property(x=>x.Unidade).HasMaxLength(20); b.Property(x=>x.Localizacao).HasMaxLength(100); b.Property(x=>x.StockAtual).HasPrecision(18,3); b.Property(x=>x.StockMinimo).HasPrecision(18,3); b.Property(x=>x.CustoMedio).HasPrecision(18,4); b.HasIndex(x=>new{x.EmpresaId,x.Codigo}).IsUnique(); } }
